\begin{definition}
\label{def:3.1}
[Limiting value of a function]
Let $(X,d_X)$ and $(Y,d_Y)$ be metric spaces, let $E\subseteq X$, and let $f:E\to Y$. Let $x_0\in X$ be an adherent point of $E$ (equivalently: for every $\delta>0$ there exists $x\in E$ with $d_X(x,x_0)<\delta$), and let $L\in Y$. The 
limit of $f$ at $x_0$ along $E$ is $L$, written
\[
\label{eq:3.u1}
\lim_{x\to x_0;\, x\in E} f(x)=L,
\]
if for every $\varepsilon>0$ there exists $\delta>0$ such that for all $x\in E$,
\[
\label{eq:3.u2}
 d_X(x,x_0) < \delta \implies d_Y\bigl(f(x),L\bigr)<\varepsilon.
\]
\end{definition}

\begin{proposition}
\label{prop:3.1}
Let $(X,d_X)$ and $(Y,d_Y)$ be metric spaces, let $f:X\to Y$ be a function, and let $x_0\in X$. Then $f$ is continuous at $x_0$ if and only if
\[
\label{eq:3.u3}
\lim_{x\to x_0;\, x\in X} f(x)=f(x_0),
\]
i.e., for every $\varepsilon>0$ there exists $\delta>0$ such that $0<d_X(x,x_0)<\delta$ implies $d_Y(f(x),f(x_0))<\varepsilon$.

Consequently, $f$ is continuous on $X$ if and only if
\[
\label{eq:3.u4}
\lim_{x\to x_0;\, x\in X} f(x)=f(x_0)\quad\text{for all }x_0\in X.
\]
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:3.1}
By definition, $f$ is continuous at $x_0$ if and only if for every $\varepsilon>0$ there exists $\delta>0$ such that $d_X(x,x_0)<\delta$ implies $d_Y(f(x),f(x_0))<\varepsilon$. This is equivalent to the limit statement $\lim_{x\to x_0;\, x\in X} f(x)=f(x_0)$, since by definition $\lim_{x\to x_0} f(x)=L$ means: for every $\varepsilon>0$ there exists $\delta>0$ such that $0<d_X(x,x_0)<\delta$ implies $d_Y(f(x),L)<\varepsilon$, and here $L=f(x_0)$.

For the second assertion, $f$ is continuous on $X$ if and only if $f$ is continuous at every $x_0\in X$, and by the first part this holds if and only if $\lim_{x\to x_0;\, x\in X} f(x)=f(x_0)$ for all $x_0\in X$.
\end{proof}

