\begin{proposition}
\label{prop:3.2}
Let $(X,d_X)$ and $(Y,d_Y)$ be metric spaces, let $E\subseteq X$, let $f:E\to Y$ be a function, and let $x_0\in X$ be an adherent point of $E$. Fix $L\in Y$. The following statements are equivalent:
\begin{enumerate}
\item[(a)] $\lim_{x\to x_0;\,x\in E} f(x)=L$, i.e. for every $\varepsilon>0$ there exists $\delta>0$ such that for all $x\in E$, if $0<d_X(x,x_0)<\delta$ then $d_Y(f(x),L)<\varepsilon$.
\item[(b)] For every sequence $(x^{(n)})_{n\ge 1}$ in $E$ with $x^{(n)}\to x_0$ in $(X,d_X)$ and $x^{(n)}\neq x_0$ for all $n$, the sequence $\bigl(f(x^{(n)})\bigr)_{n\ge 1}$ converges to $L$ in $(Y,d_Y)$.
\item[(c)] For every open set $V\subseteq Y$ with $L\in V$, there exists an open set $U\subseteq X$ with $x_0\in U$ such that $f(U\cap E\setminus\{x_0\})\subseteq V$.
\item[(d)] Define $g:E\cup\{x_0\}\to Y$ by $g(x_0):=L$ and $g(x):=f(x)$ for $x\in E\setminus\{x_0\}$. Then $g$ is continuous at $x_0$. In addition, if $x_0\in E$ and $f$ is continuous at $x_0$ (as a function on $E$ with the subspace metric), then $f(x_0)=L$.
\end{enumerate}
\end{proposition}

\begin{proposition}
\label{prop:3.3}
[Uniqueness of limit]
Let $(X,d_X)$ and $(Y,d_Y)$ be metric spaces, let $E\subseteq X$, let $f:E\to Y$, and let $x_0\in X$ be an adherent point of $E$. If $L,M\in Y$ satisfy
\[
\label{eq:3.u6}
\lim_{x\to x_0;\,x\in E} f(x)=L\quad\text{and}\quad \lim_{x\to x_0;\,x\in E} f(x)=M,
\]
then $L=M$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:3.3}
Assume $\lim_{x\to x_0;\,x\in E} f(x)=L$ and $\lim_{x\to x_0;\,x\in E} f(x)=M$. Suppose for contradiction that $L\neq M$. Set $\varepsilon:=\tfrac12 d_Y(L,M)>0$.

By the definition of limit, there exists $\delta_1>0$ such that for all $x\in E$ with $0<d_X(x,x_0)<\delta_1$, one has $d_Y(f(x),L)<\varepsilon$. Likewise, there exists $\delta_2>0$ such that for all $x\in E$ with $0<d_X(x,x_0)<\delta_2$, one has $d_Y(f(x),M)<\varepsilon$. Let $\delta:=\min\{\delta_1,\delta_2\}>0$.

Since $x_0$ is an adherent point of $E$, there exists $x\in E$ with $0<d_X(x,x_0)<\delta$. For this $x$, both inequalities hold, hence by the triangle inequality,
\[
\label{eq:3.u7}
d_Y(L,M)\le d_Y(L,f(x))+d_Y(f(x),M)<\varepsilon+\varepsilon=2\varepsilon=d_Y(L,M),
\]
a contradiction. Therefore $L=M$.
\end{proof}

