\begin{prop}
\label{prop:3.2.7}
[Moving bump: pointwise convergence does not commute with integration]
For each $n\in\mathbb N$, define $f_n:\mathbb R\to\mathbb R$ by
\[
f_n(x)=
\begin{cases}
1, & x\in [n,n+1],\\
0, & \text{otherwise}.
\end{cases}
\]
Then:
\begin{enumerate}
\item $f_n(x)\to 0$ pointwise on $\mathbb R$.
\item $\displaystyle \int_{\mathbb R} f_n(x)\,dx = 1$ for all $n$.
\item $\displaystyle \int_{\mathbb R} \lim_{n\to\infty} f_n(x)\,dx = 0$.
\end{enumerate}
Hence
\[
\lim_{n\to\infty}\int_{\mathbb R} f_n(x)\,dx \neq \int_{\mathbb R} \lim_{n\to\infty} f_n(x)\,dx.
\]
\end{prop}

proof:
\begin{proof}
Fix $x\in\mathbb R$. If $n>x$, then $x\notin[n,n+1]$, so $f_n(x)=0$ for all sufficiently large $n$; hence $f_n(x)\to 0$ pointwise.
Also, $\int_{\mathbb R} f_n=\int_n^{n+1}1\,dx=1$ for every $n$.
Since the pointwise limit is the zero function, its integral is $0$.
\end{proof}

