\begin{prop}
\label{prop:3.2.8}
[Pointwise limit of $x^n$ on $[0,1]$]
Let $f_n:[0,1]\to\mathbb R$ be $f_n(x)=x^n$. Then $f_n\to f$ pointwise on $[0,1]$, where
\[
f(x)=
\begin{cases}
0, & 0\le x<1,\\
1, & x=1.
\end{cases}
\]
\end{prop}

proof:
\begin{proof}
If $0\le x<1$, then $x^n\to 0$ as $n\to\infty$. If $x=1$, then $x^n=1$ for all $n$.
\end{proof}

