\begin{prop}
\label{prop:3.2.9}
[$x^n$ does not converge uniformly on $[0,1]$]
Let $f_n(x)=x^n$ on $[0,1]$, and let $f$ be the pointwise limit above. Then $f_n\not\to f$ uniformly on $[0,1]$.
\end{prop}

\begin{definition}
\label{def:3.3}
[Uniform convergence]
Let $(X,d_X)$ and $(Y,d_Y)$ be metric spaces. Let $(f^{(n)})_{n=1}^{\infty}$ be a sequence of functions $f^{(n)}:X\to Y$, and let $f:X\to Y$ be a function. The sequence $(f^{(n)})_{n=1}^{\infty}$ is said to \emph{converge uniformly} to $f$ on $X$ if for every $\epsilon>0$ there exists $N\in\mathbb{N}$ such that for all $n\ge N$ and all $x\in X$,
\[
\label{eq:3.u11}
d_Y\bigl(f^{(n)}(x),f(x)\bigr)<\epsilon.
\]
If this holds, then $f$ is called the \emph{uniform limit} of the sequence $(f^{(n)})_{n=1}^{\infty}$ on $X$.
\end{definition}

\begin{proposition}
\label{prop:3.4}
Let $(X,d_X)$ and $(Y,d_Y)$ be metric spaces. Let $(f^{(n)})_{n=1}^\infty$ be a sequence of functions $f^{(n)}:X\to Y$, and let $f:X\to Y$. If $f^{(n)}$ converges uniformly to $f$ on $X$, then $f^{(n)}$ converges pointwise to $f$ on $X$, i.e., for every $x\in X$ one has $d_Y\bigl(f^{(n)}(x),f(x)\bigr)\to 0$ as $n\to\infty$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:3.4}
Assume $f^{(n)}\to f$ uniformly on $X$. Let $x\in X$ be arbitrary and let $\varepsilon>0$. By uniform convergence, there exists $N\in\mathbb{N}$ such that for all $n\ge N$ and all $t\in X$,
\[
\label{eq:3.u12}
d_Y\bigl(f^{(n)}(t),f(t)\bigr)<\varepsilon.
\]
In particular, for all $n\ge N$,
\[
\label{eq:3.u13}
d_Y\bigl(f^{(n)}(x),f(x)\bigr)<\varepsilon.
\]
Therefore $d_Y\bigl(f^{(n)}(x),f(x)\bigr)\to 0$ as $n\to\infty$. Since $x\in X$ was arbitrary, $f^{(n)}$ converges pointwise to $f$ on $X$.
\end{proof}

