\begin{proposition}
[Uniform convergence of $x/n$ on $[0,1]$]
\label{prop:3.2.11}
Let $f_n:[0,1]\to\mathbb R$ be defined by
\[
f_n(x)=\frac{x}{n},
\]
and let $f:[0,1]\to\mathbb R$ be the zero function $f(x)=0$.  
Then $f_n$ converges to $f$ uniformly on $[0,1]$.
\end{proposition}

\begin{proposition}
\label{prop:3.2.12}
Let $X$ be a set, let $(Y,d)$ be a metric space, let $E\subseteq X$, and let $f^{(n)}:X\to Y$ and $f:X\to Y$.
\begin{enumerate}
\item If $f^{(n)}\to f$ pointwise on $X$, then $f^{(n)}|_E\to f|_E$ pointwise on $E$.
\item If $f^{(n)}\to f$ uniformly on $X$, then $f^{(n)}|_E\to f|_E$ uniformly on $E$.
\end{enumerate}
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:3.2.12}
(1) Assume $f^{(n)}\to f$ pointwise on $X$. For any $x\in E$, since $x\in X$, one has $d\bigl(f^{(n)}(x),f(x)\bigr)\to 0$ as $n\to\infty$. Because $f^{(n)}|_E(x)=f^{(n)}(x)$ and $f|_E(x)=f(x)$, it follows that $d\bigl(f^{(n)}|_E(x),f|_E(x)\bigr)\to 0$. Thus $f^{(n)}|_E\to f|_E$ pointwise on $E$.

(2) Assume $f^{(n)}\to f$ uniformly on $X$. Then for every $\varepsilon>0$ there exists $N\in\mathbb{N}$ such that for all $n\ge N$ and all $x\in X$, $d\bigl(f^{(n)}(x),f(x)\bigr)<\varepsilon$. In particular, for all $n\ge N$ and all $x\in E\subseteq X$, $d\bigl(f^{(n)}|_E(x),f|_E(x)\bigr)=d\bigl(f^{(n)}(x),f(x)\bigr)<\varepsilon$. Hence $f^{(n)}|_E\to f|_E$ uniformly on $E$.
\end{proof}

