\begin{theorem}
\label{thm:3.3.1}
[Uniform limits preserve continuity I]
Suppose $(X,d_X)$ and $(Y,d_Y)$ are metric spaces. Let $(f^{(n)})_{n=1}^{\infty}$ be a sequence of functions $f^{(n)}:X\to Y$ that converges uniformly on $X$ to a function $f:X\to Y$. Fix $x_0\in X$. If each $f^{(n)}$ is continuous at $x_0$, then $f$ is continuous at $x_0$.
\end{theorem}

proof:
\begin{proof}
\label{prf:thm:3.3.1}
Fix $\varepsilon>0$. By uniform convergence of $f^{(n)}$ to $f$, there exists $N\in\mathbb{N}$ such that for all $x\in X$,
\[
\label{eq:3.u23}
d_Y\bigl(f^{(N)}(x),f(x)\bigr)<\varepsilon/3.
\]
Since $f^{(N)}$ is continuous at $x_0$, there exists $\delta>0$ such that whenever $d_X(x,x_0)<\delta$,
\[
\label{eq:3.u24}
d_Y\bigl(f^{(N)}(x),f^{(N)}(x_0)\bigr)<\varepsilon/3.
\]
For such $x$, the triangle inequality gives
\[
\label{eq:3.u25}
\begin{aligned}
d_Y\bigl(f(x),f(x_0)\bigr)
&\le d_Y\bigl(f(x),f^{(N)}(x)\bigr)+d_Y\bigl(f^{(N)}(x),f^{(N)}(x_0)\bigr)+d_Y\bigl(f^{(N)}(x_0),f(x_0)\bigr)\\
&<\varepsilon/3+\varepsilon/3+\varepsilon/3=\varepsilon.
\end{aligned}
\]
Thus, for every $\varepsilon>0$ there exists $\delta>0$ such that $d_X(x,x_0)<\delta$ implies $d_Y(f(x),f(x_0))<\varepsilon$, so $f$ is continuous at $x_0$.
\end{proof}

