\begin{theorem}
\label{thm:3.3.2}
[Uniform limits preserve continuity]
Let $(X,d_X)$ and $(Y,d_Y)$ be metric spaces. Let $(f^{(n)})_{n=1}^{\infty}$ be a sequence of functions $f^{(n)}:X\to Y$ that converges uniformly to a function $f:X\to Y$. If each $f^{(n)}$ is continuous at every point of $X$, then $f$ is continuous at every point of $X$.
\end{theorem}

proof:
\begin{proof}
\label{prf:thm:3.3.2}
Fix $x\in X$ and let $\varepsilon>0$. By uniform convergence, there exists $N\in\mathbb{N}$ such that for all $n\ge N$ and all $z\in X$,
\[
\label{eq:3.u26}
d_Y\bigl(f^{(n)}(z),f(z)\bigr)<\frac{\varepsilon}{3}.
\]
Since $f^{(N)}$ is continuous at $x$, there exists $\delta>0$ such that if $d_X(z,x)<\delta$, then
\[
\label{eq:3.u27}
d_Y\bigl(f^{(N)}(z),f^{(N)}(x)\bigr)<\frac{\varepsilon}{3}.
\]
For any $z\in X$ with $d_X(z,x)<\delta$, the triangle inequality gives
\[
\label{eq:3.u28}
\begin{aligned}
d_Y\bigl(f(z),f(x)\bigr)
&\le d_Y\bigl(f(z),f^{(N)}(z)\bigr)+d_Y\bigl(f^{(N)}(z),f^{(N)}(x)\bigr)+d_Y\bigl(f^{(N)}(x),f(x)\bigr) \\
&<\frac{\varepsilon}{3}+\frac{\varepsilon}{3}+\frac{\varepsilon}{3}=\varepsilon.
\end{aligned}
\]
Thus for every $\varepsilon>0$ there exists $\delta>0$ such that $d_X(z,x)<\delta$ implies $d_Y(f(z),f(x))<\varepsilon$, so $f$ is continuous at $x$. Since $x\in X$ was arbitrary, $f$ is continuous on $X$.
\end{proof}

