\begin{proposition}
\label{prop:3.3.3}
[Interchange of limits and uniform limits]
Let $(X,d_X)$ and $(Y,d_Y)$ be metric spaces with $Y$ complete, and let $E\subseteq X$. Let $(f^{(n)})_{n\ge 1}$ be a sequence of functions $f^{(n)}:E\to Y$ that converges uniformly on $E$ to a function $f:E\to Y$. Let $x_0\in X$ be an adherent point of $E$, and suppose that for each $n\ge 1$ the limit
\[
\label{eq:3.u29}
\ell_n:=\lim_{x\to x_0;\,x\in E} f^{(n)}(x)
\]
exists in $Y$. Then the sequence $(\ell_n)_{n\ge 1}$ converges in $Y$, the limit
\[
\label{eq:3.u30}
\lim_{x\to x_0;\,x\in E} f(x)
\]
exists in $Y$, and
\[
\label{eq:3.u31}
\lim_{n\to\infty}\,\lim_{x\to x_0;\, x\in E} f^{(n)}(x)
=\lim_{x\to x_0;\, x\in E}\,\lim_{n\to\infty} f^{(n)}(x).
\]
\end{proposition}

\begin{proposition}
\label{prop:3.3.4}
Let $(X,d_X)$ and $(Y,d_Y)$ be metric spaces. Let $f^{(n)}:X\to Y$ be continuous for each $n\in\mathbb{N}$, and suppose that $f^{(n)}\to f:X\to Y$ uniformly on $X$. If $(x^{(n)})_{n=1}^\infty$ is a sequence in $X$ such that $x^{(n)}\to x\in X$, then $f^{(n)}(x^{(n)})\to f(x)$ in $Y$.
\end{proposition}

\begin{definition}
\label{def:3.4}
Let $(X,d_X)$ and $(Y,d_Y)$ be metric spaces, and let $f:X\to Y$ be a function. The function $f$ is called \emph{bounded} if its image $f(X)=\{f(x):x\in X\}$ is a bounded subset of $Y$, that is, if there exist $y_0\in Y$ and $R>0$ such that $d_Y\bigl(f(x),y_0\bigr)<R$ for all $x\in X$ (equivalently, $f(x)\in B_{(Y,d_Y)}(y_0,R)$ for all $x\in X$).
\end{definition}

\begin{proposition}
\label{prop:3.3.5}
(Uniform limits preserve boundedness) Let $(X,d_X)$ and $(Y,d_Y)$ be metric spaces. Let $(f^{(n)})_{n\ge 1}$ be a sequence of functions $f^{(n)}:X\to Y$ and let $f:X\to Y$ be a function such that $f^{(n)}\to f$ uniformly on $X$. If each $f^{(n)}$ is bounded on $X$, then $f$ is bounded on $X$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:3.3.5}
By uniform convergence, there exists $N\in\mathbb{N}$ such that for all $n\ge N$ and all $x\in X$,
\[
\label{eq:3.u42}
d_Y\bigl(f^{(n)}(x),f(x)\bigr)<1.
\]
Since $f^{(N)}$ is bounded on $X$, there exist $x_0\in X$ and $M\ge 0$ such that for all $x\in X$,
\[
\label{eq:3.u43}
d_Y\bigl(f^{(N)}(x),f^{(N)}(x_0)\bigr)\le M.
\]
Fix such an $x_0$. For any $x\in X$, the triangle inequality gives
\[
\label{eq:3.u44}
\begin{aligned}
d_Y\bigl(f(x),f(x_0)\bigr)
&\le d_Y\bigl(f(x),f^{(N)}(x)\bigr)+d_Y\bigl(f^{(N)}(x),f^{(N)}(x_0)\bigr)+d_Y\bigl(f^{(N)}(x_0),f(x_0)\bigr)\\
&< 1 + M + 1 = M+2.
\end{aligned}
\]
Thus $d_Y(f(x),f(x_0))\le M+2$ for all $x\in X$, so $f$ is bounded on $X$.
\end{proof}

