\begin{proposition}
[Uniform limits preserve boundedness]\label{prop:3.3.6}
Let $(X,d_X)$ and $(Y,d_Y)$ be metric spaces.
Let $(f^{(n)})_{n=1}^\infty$ be a sequence of functions
$f^{(n)}:X\to Y$ converging uniformly to a function $f:X\to Y$.
If each $f^{(n)}$ is bounded on $X$, then $f$ is bounded on $X$.
\end{proposition}

\begin{definition}
\label{def:3.6}
[Uniform (supremum) metric]
Assume $X\neq\varnothing$. For $f,g\in B(X\to Y)$ define
\[
d_\infty(f,g):=\sup_{x\in X} d_Y\bigl(f(x),g(x)\bigr)\in[0,\infty).
\]
If $X=\varnothing$, set $d_\infty(f,g):=0$ for all $f,g\in B(X\to Y)$.
\end{definition}

proof:
\begin{proof}
\label{prf:prop:3.4.3}
\[
d_\infty(f,g)
=\sup_{x\in[0,1]} d_Y\bigl(f(x),g(x)\bigr)
=\sup_{x\in[0,1]} |2x-3x|
=\sup_{x\in[0,1]} |x|
=1.
\]
\end{proof}

content:
\begin{proposition}
\label{prop:3.4.4}Let $(X,d_X)$ and $(Y,d_Y)$ be metric spaces. Let $(f^{(n)})_{n\ge 1}$ be a sequence
in $B(X\to Y)$ and let $f\in B(X\to Y)$. Then the following are equivalent:
\begin{enumerate}
\item $d_\infty\bigl(f^{(n)},f\bigr)\to 0$ as $n\to\infty$;
\item $f^{(n)}\to f$ uniformly on $X$, i.e. for every $\varepsilon>0$ there exists
$N$ such that for all $n\ge N$ and all $x\in X$,
\[
d_Y\bigl(f^{(n)}(x),f(x)\bigr)<\varepsilon.
\]
\end{enumerate}
\end{proposition}

\begin{definition}
\label{def:3.7}
[Bounded continuous functions]
Let $(X,d_X)$ and $(Y,d_Y)$ be metric spaces. Define the space of bounded continuous
functions from $X$ to $Y$ by
\[
C(X\to Y):=\{\,f\in B(X\to Y)\mid f \text{ is continuous}\,\}.
\]
\end{definition}

proof:
\begin{proof}
\label{prf:prop:3.4.5}
By definition, every $f\in C(X\to Y)$ is an element of $B(X\to Y)$ (and is moreover
continuous). Hence the inclusion holds.
\end{proof}

content:
\begin{proposition}
\label{prop:3.4.6}[Uniform limits preserve continuity]
Let $(X,d_X)$ and $(Y,d_Y)$ be metric spaces, then  $C(X → Y)$ is closed in $B(X → Y)$. That is to say, let $(f^{(n)})_{n\ge1}$ be a sequence
of functions $X\to Y$ converging uniformly to $f\colon X\to Y$ (with respect to the
uniform metric $d_\infty$). If each $f^{(n)}$ is continuous, then $f$ is continuous.
\end{proposition}

\begin{definition}
\label{def:3.8}
[Finite sum of real-valued functions]
Let $(X,d_X)$ be a metric space and let $f^{(1)},\ldots,f^{(N)}:X\to\mathbb{R}$. The \emph{finite sum} $\sum_{i=1}^N f^{(i)}:X\to\mathbb{R}$ is defined by
\[
\label{eq:3.u73}
\left(\sum_{i=1}^N f^{(i)}\right)(x):=\sum_{i=1}^N f^{(i)}(x), \qquad x\in X.
\]
\end{definition}

\begin{proposition}
\label{prop:3.5.3}[Finite sums of continuous functions are continuous]
Let $(X,d_X)$ be a metric space and let $Y$ be a normed vector space (with its
metric). If $f^{(1)},\dots,f^{(n)}:X\to Y$ are continuous, then
\[
f:=\sum_{i=1}^n f^{(i)}
\]
is continuous.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:3.5.3}
The addition map $+:Y\times Y\to Y$, $(u,v)\mapsto u+v$, is continuous (indeed,
$\|(u+v)-(u'+v')\|\le \|u-u'\|+\|v-v'\|$). Hence the sum of two continuous functions
is continuous. Applying this repeatedly (or using induction on $n$) shows that the
finite sum $\sum_{i=1}^n f^{(i)}$ is continuous.
\end{proof}

