\begin{definition}
\label{def:3.9}
[Infinite series of functions]
Let $(X,d_X)$ be a metric space, and let $(f^{(n)})_{n\ge 1}$ be functions $f^{(n)}:X\to\mathbb{R}$. For each integer $N\ge 1$, define the partial sum function
\[
\label{eq:3.u74}
S_N:X\to\mathbb{R},\qquad S_N(x):=\sum_{n=1}^{N} f^{(n)}(x).
\]
Let $f:X\to\mathbb{R}$.
\begin{enumerate}
\item The series $\sum_{n=1}^{\infty} f^{(n)}$ \emph{converges pointwise} to $f$ on $X$ if for every $x\in X$,
\[
\label{eq:3.u75}
\lim_{N\to\infty} S_N(x)=f(x).
\]
In this case, write $f=\sum_{n=1}^{\infty} f^{(n)}$.
\item The series $\sum_{n=1}^{\infty} f^{(n)}$ \emph{converges uniformly} to $f$ on $X$ if $S_N\to f$ uniformly on $X$, i.e., if
\[
\label{eq:3.u76}
\lim_{N\to\infty}\sup_{x\in X}\bigl|S_N(x)-f(x)\bigr|=0.
\]
In this case, write $f=\sum_{n=1}^{\infty} f^{(n)}$.
\end{enumerate}
\end{definition}

\begin{proposition}
\label{prop:3.17}
Let $X$ be a set, let $f^{(n)}:X\to\mathbb{R}$ be functions for $n\in\mathbb{N}$, and let $f:X\to\mathbb{R}$. Suppose that the series $\sum_{n=1}^{\infty} f^{(n)}$ converges uniformly to $f$ on $X$, meaning that the sequence of partial sums $S_N(x)=\sum_{n=1}^N f^{(n)}(x)$ converges uniformly to $f$ on $X$. Then $\sum_{n=1}^{\infty} f^{(n)}$ converges pointwise to $f$ on $X$, i.e., for every $x\in X$ one has $\lim_{N\to\infty} S_N(x)=f(x)$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:3.17}
Let $S_N(x)=\sum_{n=1}^N f^{(n)}(x)$. Uniform convergence of $S_N$ to $f$ on $X$ means: for every $\varepsilon>0$ there exists $N_0\in\mathbb{N}$ such that for all $N\ge N_0$ and all $x\in X$, $|S_N(x)-f(x)|<\varepsilon$. Fix $x\in X$. Then the same $N_0$ satisfies that for all $N\ge N_0$, $|S_N(x)-f(x)|<\varepsilon$. Hence $S_N(x)\to f(x)$ as $N\to\infty$. Since $x\in X$ was arbitrary, the convergence is pointwise to $f$ on $X$.
\end{proof}

