\begin{definition}
\label{def:3.10}
[Sup norm]
Let $X$ be a set and let $f:X\to\mathbb{R}$ be a bounded function, i.e. there exists $M\ge 0$ such that $|f(x)|\le M$ for all $x\in X$. The \emph{sup norm} (or \emph{uniform norm}) of $f$ is
\[
\label{eq:3.u77}
\|f\|_\infty := \sup\{\,|f(x)| : x\in X\,\}.
\]
If $X=\varnothing$, define $\|f\|_\infty:=0$.
\end{definition}

proof:
\begin{proof}
\label{prf:prop:3.5.4}
Since $|f(x)|\ge 0$ for all $x$, the supremum is $\ge 0$.
Because $f$ is bounded, there exists $M<\infty$ such that $|f(x)|\le M$ for all $x$.
Hence $\sup_{x\in X}|f(x)|\le M<\infty$, so $\|f\|_\infty$ is finite.
\end{proof}

