\begin{theorem}
\label{thm:3.5}
[Weierstrass $M$-test]
Let $(X,d)$ be a metric space, and let $(f^{(n)})_{n=1}^{\infty}$ be a sequence of bounded real-valued continuous functions on $X$. Assume that the series
\[
\label{eq:3.u78}
\sum_{n=1}^{\infty}\|f^{(n)}\|_{\infty}
\]
converges, where $\|f^{(n)}\|_{\infty}=\sup_{x\in X}|f^{(n)}(x)|$. Then the series of functions $\sum_{n=1}^{\infty} f^{(n)}$ converges uniformly on $X$ to a function $f\colon X\to\mathbb{R}$. Moreover, $f$ is continuous on $X$.
\end{theorem}

\begin{theorem}
\label{thm:3.6}
Let $a<b$ be real numbers. For each integer $n\ge 1$, let $f^{(n)}:[a,b]\to\mathbb{R}$ be Riemann integrable, and assume that $f^{(n)}\to f$ uniformly on $[a,b]$ for some function $f:[a,b]\to\mathbb{R}$. Then $f$ is Riemann integrable and
\[
\label{eq:3.u84}
\lim_{n\to\infty}\int_{[a,b]} f^{(n)}=\int_{[a,b]} f.
\]
\end{theorem}

\begin{theorem}
\label{thm:3.7}
[Interchange of limit and integral under uniform convergence]
Let $[a,b]\subset\mathbb{R}$ be a compact interval. Let $\{f^{(n)}\}_{n\in\mathbb{N}}$ be a sequence of Riemann-integrable functions on $[a,b]$ such that $f^{(n)}\to f$ uniformly on $[a,b]$. Then $f$ is Riemann-integrable on $[a,b]$ and
\[
\label{eq:3.u94}
\lim_{n\to\infty}\int_a^b f^{(n)}(x)\,dx \,=\, \int_a^b \lim_{n\to\infty} f^{(n)}(x)\,dx \,=\, \int_a^b f(x)\,dx.
\]
\end{theorem}

\begin{theorem}
\label{thm:3.8}
Let $a<b$ and let $\{f^{(n)}\}_{n=1}^\infty$ be a sequence of Riemann-integrable functions on $[a,b]$. Assume that the series $\sum_{n=1}^\infty f^{(n)}(x)$ converges uniformly on $[a,b]$ to a function $s(x)$. Then $s$ is Riemann-integrable on $[a,b]$ and
\[
\label{eq:3.u101}
\int_{[a,b]} s(x)\,dx=\sum_{n=1}^\infty \int_{[a,b]} f^{(n)}(x)\,dx.
\]
\end{theorem}

\begin{proposition}
\label{prop:3.18}
For every real number $r$ with $0<r<1$, the following identity holds:
\[
\label{eq:3.u111}
-\log(1-r)=\sum_{n=0}^{\infty}\frac{r^{n+1}}{n+1}.
\]
\end{proposition}

\begin{proposition}
\label{prop:3.19}
Define $f_n:[0,2\pi]\to\mathbb{R}$ by $f_n(x):=n^{-1/2}\sin(nx)$ and $f:[0,2\pi]\to\mathbb{R}$ by $f(x):=0$. Then $f_n\to f$ uniformly on $[0,2\pi]$, but $(f_n')$ does not converge pointwise to $f'$ (hence does not converge uniformly). In particular,
\[
\label{eq:3.u116}
\frac{d}{dx}\lim_{n\to\infty} f_n(x)\neq \lim_{n\to\infty}\frac{d}{dx}f_n(x).
\]
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:3.19}
Since $|\sin(nx)|\le 1$ for all $x$, one has
\[
\label{eq:3.u117}
\sup_{x\in[0,2\pi]}|f_n(x)-f(x)|=\sup_{x\in[0,2\pi]} n^{-1/2}|\sin(nx)|\le n^{-1/2}\to 0,
\]
so $f_n\to f$ uniformly. Moreover $f_n'(x)=n^{1/2}\cos(nx)$ for all $x$, while $f'(x)=0$. Hence $|f_n'(0)-f'(0)|=|n^{1/2}\cos(0)-0|=n^{1/2}\to\infty$, so $f_n'$ does not converge pointwise to $f'$.
\end{proof}

