\begin{proposition}
\label{prop:3.20}
Define $f_n:[-1,1]\to\mathbb{R}$ by $f_n(x):=\sqrt{\frac{1}{n^2}+x^2}$ and $f(x):=|x|$. Then $f_n\to f$ uniformly on $[-1,1]$, each $f_n$ is differentiable on $[-1,1]$, and $f$ is not differentiable at $0$. In particular, a uniform limit of differentiable functions need not be differentiable.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:3.20}
For all $x\in[-1,1]$, one has $|x|\le \sqrt{x^2+\frac{1}{n^2}}$ since squaring gives $x^2\le x^2+\frac{1}{n^2}$. Also,
\[
\label{eq:3.u118}
\sqrt{x^2+\frac{1}{n^2}}\le |x|+\frac{1}{n}
\]
since squaring the right-hand side yields $x^2+\frac{2|x|}{n}+\frac{1}{n^2}\ge x^2+\frac{1}{n^2}$. Therefore $0\le f_n(x)-|x|\le \frac{1}{n}$ for all $x$, so
\[
\label{eq:3.u119}
\sup_{x\in[-1,1]}|f_n(x)-f(x)|\le \frac{1}{n}\to 0,
\]
which implies uniform convergence $f_n\to f$. Each $f_n$ is differentiable on $[-1,1]$ as a composition of differentiable functions with strictly positive radicand. Finally, $f(x)=|x|$ is not differentiable at $0$ because the one-sided difference quotients satisfy
\[
\label{eq:3.u120}
\lim_{h\downarrow 0}\frac{|h|-|0|}{h}=1,\qquad \lim_{h\uparrow 0}\frac{|h|-|0|}{h}=-1,
\]
so the derivative at $0$ does not exist.
\end{proof}

