\begin{theorem}
\label{thm:3.9}
Let $[a,b]$ be an interval. For each integer $n\ge 1$, let $f_n:[a,b]\to\mathbb{R}$ be differentiable and assume $f_n'$ is continuous on $[a,b]$. Suppose $f_n'\to g$ uniformly on $[a,b]$ for some function $g:[a,b]\to\mathbb{R}$. Assume there exists $x_0\in[a,b]$ such that $\lim_{n\to\infty} f_n(x_0)$ exists. Then there exists a differentiable function $f:[a,b]\to\mathbb{R}$ such that $f_n\to f$ uniformly on $[a,b]$ and $f'(x)=g(x)$ for all $x\in[a,b]$.
\end{theorem}

\begin{theorem}
\label{thm:3.10}
Let $[a,b]$ be an interval. For each integer $n\ge 1$, let $f_n:[a,b]\to\mathbb{R}$ be differentiable and assume $f_n':[a,b]\to\mathbb{R}$ is continuous. Assume the series $\sum_{n=1}^\infty \|f_n'\|_\infty$ converges, where
\[
\label{eq:3.u126}
\|f_n'\|_\infty:=\sup_{x\in[a,b]}|f_n'(x)|.
\]
Assume also that $\sum_{n=1}^\infty f_n(x_0)$ converges for some $x_0\in[a,b]$. Then the series $\sum_{n=1}^\infty f_n$ converges uniformly on $[a,b]$ to a differentiable function $f$, and
\[
\label{eq:3.u127}
f'(x)=\frac{d}{dx}\sum_{n=1}^\infty f_n(x)=\sum_{n=1}^\infty f_n'(x)
\]
for all $x\in[a,b]$.
\end{theorem}

\begin{definition}
\label{def:3.11}
[Weierstrass function]\label{def:weierstrass-function}
Let $f:\mathbb{R}\to\mathbb{R}$ be defined by
\[
\label{eq:3.u128}
f(x):=\sum_{n=1}^{\infty}4^{-n}\cos(32^n\pi x).
\]
\end{definition}

\begin{proposition}
\label{prop:3.21}
\label{prop:weierstrass-continuity}
The function $f$ of Definition~\ref{def:weierstrass-function} is continuous on $\mathbb{R}$.
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:3.21}
For each $n\ge 1$, the function $x\mapsto 4^{-n}\cos(32^n\pi x)$ is continuous on $\mathbb{R}$ and satisfies $\lvert 4^{-n}\cos(32^n\pi x)\rvert\le 4^{-n}$ for all $x\in\mathbb{R}$. Since $\sum_{n=1}^\infty 4^{-n}$ converges, the Weierstrass $M$-test implies that $\sum_{n=1}^{\infty}4^{-n}\cos(32^n\pi x)$ converges uniformly on $\mathbb{R}$. A uniform limit of continuous functions is continuous, hence $f$ is continuous on $\mathbb{R}$.
\end{proof}

