\label{eq:3.u130}
f(x)=\sum_{i=0}^{n} c_i x^i \quad \text{for all } x\in[a,b].
\]
If $f$ is a polynomial and $n$ is the largest index such that $c_n\ne 0$, then $n$ is called the \emph{degree} of $f$.
\end{definition}

