\begin{theorem}
\label{thm:3.11}
[Weierstrass approximation theorem]
Let $a<b$ be real numbers, and let $f:[a,b]\to\mathbb{R}$ be continuous. For every $\varepsilon>0$ there exists a polynomial $P$ (with real coefficients) such that
\[
\label{eq:3.u131}
\sup_{x\in[a,b]}|P(x)-f(x)|\le \varepsilon.
\]
Equivalently, if $C([a,b]\to\mathbb{R})$ denotes the set of continuous functions $[a,b]\to\mathbb{R}$ equipped with the uniform metric $d_\infty(f,g)=\sup_{x\in[a,b]}|f(x)-g(x)|$, and if $P([a,b]\to\mathbb{R})$ denotes the subset of polynomial functions on $[a,b]$, then
\[
\label{eq:3.u132}
\overline{P([a,b]\to\mathbb{R})}=C([a,b]\to\mathbb{R})
\]
(where the closure is taken with respect to $d_\infty$).
\end{theorem}

\begin{definition}
\label{def:3.13}
[Compactly supported functions]
A function $f:\mathbb{R}\to\mathbb{R}$ is \emph{supported on} a closed interval $[a,b]\subset\mathbb{R}$ if $f(x)=0$ for all $x\in\mathbb{R}\setminus [a,b]$. The function $f$ is \emph{compactly supported} if there exist real numbers $a\le b$ such that $f$ is supported on $[a,b]$.

If $f$ is continuous and supported on $[a,b]$, define
\[
\label{eq:3.u144}
\int_{-\infty}^{\infty} f(x)\,dx := \int_a^b f(x)\,dx.
\]
\end{definition}

\begin{lemma}
\label{lem:3.1}
Let $f:\mathbb{R}\to\mathbb{R}$ be continuous. Suppose $f$ is supported on $[a,b]$ and also supported on $[c,d]$, i.e.
\[
\label{eq:3.u145}
f(x)=0\quad\text{for all }x\notin[a,b],\qquad f(x)=0\quad\text{for all }x\notin[c,d].
\]
Then the integrals of $f$ over these intervals agree:
\[
\label{eq:3.u146}
\int_{a}^{b} f(x)\,dx = \int_{c}^{d} f(x)\,dx.
\]
\end{lemma}

proof:
\begin{proof}
\label{prf:lem:3.1}
Since $f$ is supported on $[a,b]$, one has $f(x)=0$ for all $x\in [c,d]\setminus [a,b]$, and hence
\[
\label{eq:3.u147}
\int_c^d f(x)\,dx=\int_{[c,d]\cap[a,b]} f(x)\,dx.
\]
Similarly, since $f$ is supported on $[c,d]$, one has $f(x)=0$ for all $x\in [a,b]\setminus [c,d]$, and hence
\[
\label{eq:3.u148}
\int_a^b f(x)\,dx=\int_{[a,b]\cap[c,d]} f(x)\,dx.
\]
The right-hand sides are equal because $[c,d]\cap[a,b]=[a,b]\cap[c,d]$. Therefore $\int_a^b f(x)\,dx=\int_c^d f(x)\,dx$.
\end{proof}

