\begin{definition}
\label{def:3.14}
[Approximation to the identity]
Let $\varepsilon>0$ and $0<\delta<1$. A function $f:\mathbb{R}\to\mathbb{R}$ is called an $(\varepsilon,\delta)$-approximation to the identity if it satisfies the following conditions:
\begin{enumerate}
\item $\operatorname{supp}(f)\subseteq[-1,1]$ and $f(x)\ge 0$ for all $x\in\mathbb{R}$.
\item $f$ is continuous on $\mathbb{R}$ and $\int_{-\infty}^{\infty} f(x)\,dx=1$.
\item For every $x\in\mathbb{R}$ with $\delta\le |x|\le 1$, one has $|f(x)|\le \varepsilon$.
\end{enumerate}
\end{definition}

\begin{lemma}
\label{lem:3.2}
[Polynomials can approximate the identity]
For every $\varepsilon>0$ and every $\delta$ with $0<\delta<1$, there exists a polynomial $P\in\mathbb{R}[x]$ such that
\[
\label{eq:3.u149}
|P(x)-x|\le \varepsilon\quad\text{for all }x\in[-1,-\delta]\cup[\delta,1].
\]
In particular, $P$ is an $(\varepsilon,\delta)$-approximation to the identity on $[-1,1]$.
\end{lemma}

proof:
\begin{proof}
\label{prf:lem:3.2}
Define a continuous function $f:[-1,1]\to\mathbb{R}$ by
\[
\label{eq:3.u150}
f(x)=\begin{cases}
x,& |x|\ge \delta,\\
\dfrac{x^3}{\delta^2},& |x|\le \delta.
\end{cases}
\]
Then $f$ is continuous on $[-1,1]$, since the two definitions agree at $x=\pm\delta$.
Moreover, for $|x|\ge\delta$ one has $f(x)=x$.

By the Weierstrass approximation theorem, there exists a polynomial $P$ such that
\[
\label{eq:3.u151}
\sup_{x\in[-1,1]} |P(x)-f(x)|\le \varepsilon.
\]
For $x\in[-1,-\delta]\cup[\delta,1]$ this implies
\[
\label{eq:3.u152}
|P(x)-x|=|P(x)-f(x)|\le \varepsilon.
\]
Thus $P$ is an $(\varepsilon,\delta)$-approximation to the identity on $[-1,1]$.
\end{proof}

