\begin{definition}
\label{def:3.15}
[Convolution]
Let $f:\mathbb{R}\to\mathbb{R}$ and $g:\mathbb{R}\to\mathbb{R}$ be continuous functions with compact support. The convolution of $f$ and $g$ is the function $f*g:\mathbb{R}\to\mathbb{R}$ defined, for each $x\in\mathbb{R}$, by
\[
\label{eq:3.u153}
(f*g)(x):=\int_{-\infty}^{\infty} f(y)\,g(x-y)\,dy.
\]
\end{definition}

\begin{proposition}
\label{prop:3.23}
(Basic properties of convolution) Let $f,g,h:\mathbb{R}\to\mathbb{R}$ be continuous functions with compact support. Define the convolution
\[
\label{eq:3.u154}
(f*g)(x)=\int_{\mathbb{R}} f(x-t)g(t)\,dt,\qquad x\in\mathbb{R}.
\]
Then the following statements hold.
\begin{enumerate}
\item The function $f*g$ is continuous on $\mathbb{R}$ and has compact support.
\item (Commutativity) For all $x\in\mathbb{R}$, $(f*g)(x)=(g*f)(x)$.
\item (Linearity) For all $x\in\mathbb{R}$, $\bigl(f*(g+h)\bigr)(x)=(f*g)(x)+(f*h)(x)$. Moreover, for any $c\in\mathbb{R}$ and all $x\in\mathbb{R}$,
\[
\label{eq:3.u155}
\bigl(f*(cg)\bigr)(x)=\bigl((cf)*g\bigr)(x)=c\,(f*g)(x).
\]
\end{enumerate}
\end{proposition}

\begin{proposition}
\label{prop:3.24}
Let $f,g,h:\mathbb{R}\to\mathbb{R}$ be functions such that each convolution appearing below is well-defined as an absolutely convergent integral.
\begin{enumerate}
\item \emph{(Associativity)} For all $x\in\mathbb{R}$,
\[
\label{eq:3.u162}
((f*g)*h)(x)=(f*(g*h))(x).
\]
\item \emph{(Derivative commutation)} Assume that $f$ and $g$ are differentiable and that $(f'*g)(x)$ and $(f*g')(x)$ are well-defined as absolutely convergent integrals for each $x$. Then $f*g$ is differentiable and, for all $x\in\mathbb{R}$,
\[
\label{eq:3.u163}
(f*g)'(x)=(f'*g)(x)=(f*g')(x).
\]
\item \emph{(Identity)} Let $\delta$ denote the Dirac delta distribution. For every (sufficiently regular) function $f$ for which convolution with $\delta$ is defined,
\[
\label{eq:3.u164}
(f*\delta)(x)=(\delta*f)(x)=f(x)\quad\text{for all }x\in\mathbb{R}.
\]
\end{enumerate}
\end{proposition}

proof:
\begin{proof}
\label{prf:prop:3.24}
Write convolution in the form
\[
\label{eq:3.u169}
(f*g)(x)=\int_{\mathbb{R}} f(x-t)g(t)\,dt,
\]
whenever the integral is absolutely convergent.

\begin{enumerate}
\item For each fixed $x$, absolute convergence of the iterated integrals below allows the use of Fubini's theorem. Compute
\begin{align*}
\label{eq:3.u165}
((f*g)*h)(x)
&=\int_{\mathbb{R}} (f*g)(x-s)h(s)\,ds
=\int_{\mathbb{R}}\left(\int_{\mathbb{R}} f((x-s)-t)g(t)\,dt\right)h(s)\,ds\\
&=\int_{\mathbb{R}}\int_{\mathbb{R}} f(x-s-t)g(t)h(s)\,dt\,ds.
\end{align*}
Similarly,
\begin{align*}
\label{eq:3.u166}
(f*(g*h))(x)
&=\int_{\mathbb{R}} f(x-u)(g*h)(u)\,du
=\int_{\mathbb{R}} f(x-u)\left(\int_{\mathbb{R}} g(u-s)h(s)\,ds\right)\,du\\
&=\int_{\mathbb{R}}\int_{\mathbb{R}} f(x-u)g(u-s)h(s)\,ds\,du.
\end{align*}
In the last double integral, make the change of variables $t=u-s$ (so $u=t+s$, $du=dt$) to obtain
\[
\label{eq:3.u170}
\int_{\mathbb{R}}\int_{\mathbb{R}} f(x-(t+s))g(t)h(s)\,dt\,ds
=\int_{\mathbb{R}}\int_{\mathbb{R}} f(x-s-t)g(t)h(s)\,dt\,ds,
\]
which matches the expression for $((f*g)*h)(x)$. Hence $((f*g)*h)(x)=(f*(g*h))(x)$ for all $x$.

\item Fix $x\in\mathbb{R}$. Consider
\[
\label{eq:3.u171}
(f*g)(x)=\int_{\mathbb{R}} f(x-t)g(t)\,dt.
\]
For each $t$, the map $x\mapsto f(x-t)$ is differentiable with derivative $f'(x-t)$. Under the stated hypotheses (absolute convergence of the relevant integrals), differentiation may be passed under the integral sign, giving
\[
\label{eq:3.u172}
(f*g)'(x)=\int_{\mathbb{R}} f'(x-t)g(t)\,dt=(f'*g)(x).
\]
To obtain the second equality, use the change of variables $s=x-t$:
\begin{align*}
\label{eq:3.u167}
(f'*g)(x)
&=\int_{\mathbb{R}} f'(x-t)g(t)\,dt
=\int_{\mathbb{R}} f'(s)g(x-s)\,ds.
\end{align*}
Since $g$ is differentiable, the function $s\mapsto g(x-s)$ has derivative $-g'(x-s)$. Integrating by parts over $\mathbb{R}$ (justified by the assumed integrability so that boundary terms vanish) yields
\begin{align*}
\label{eq:3.u168}
\int_{\mathbb{R}} f'(s)g(x-s)\,ds
&=\bigl[f(s)g(x-s)\bigr]_{-\infty}^{\infty}-\int_{\mathbb{R}} f(s)\,\frac{d}{ds}g(x-s)\,ds\\
&=\int_{\mathbb{R}} f(s)g'(x-s)\,ds=(f*g')(x).
\end{align*}
Therefore $(f*g)'=f'*g=f*g'$.

\item For any test function $\varphi$, the Dirac delta satisfies $\int_{\mathbb{R}} \delta(t)\varphi(t)\,dt=\varphi(0)$. Hence, for each $x$,
\[
\label{eq:3.u173}
(f*\delta)(x)=\int_{\mathbb{R}} f(x-t)\,\delta(t)\,dt=f(x-0)=f(x),
\]
and similarly
\[
\label{eq:3.u174}
(\delta*f)(x)=\int_{\mathbb{R}} \delta(t)f(x-t)\,dt=f(x).
\]
\end{enumerate}
\end{proof}

