\begin{lemma}
\label{lem:3.3}
Let $f:\mathbb{R}\to\mathbb{R}$ be continuous with $\operatorname{supp}(f)\subseteq[0,1]$, and let $g:\mathbb{R}\to\mathbb{R}$ be continuous with $\operatorname{supp}(g)\subseteq[-1,1]$. Assume that there exist an integer $n\ge 0$ and real coefficients $c_0,\dots,c_n$ such that
\[
\label{eq:3.u175}
g(t)=\sum_{j=0}^n c_j t^j\quad\text{for all }t\in[-1,1].
\]
Define the convolution
\[
\label{eq:3.u176}
(f*g)(x):=\int_{-\infty}^{\infty} f(y)g(x-y)\,dy.
\]
Then there exist real numbers $C_0,\dots,C_n$ such that
\[
\label{eq:3.u177}
(f*g)(x)=\sum_{k=0}^n C_k x^k\quad\text{for all }x\in[0,1].
\]
In particular, $f*g$ is a polynomial on $[0,1]$.
\end{lemma}

\begin{lemma}
\label{lem:3.4}
Let $f:\mathbb{R}\to\mathbb{R}$ be continuous, supported on $[0,1]$, and bounded by $M>0$, i.e. $|f(x)|\le M$ for all $x\in\mathbb{R}$. Let $\varepsilon>0$ and $0<\delta<1$ be such that $|f(x)-f(y)|<\varepsilon$ whenever $|x-y|<\delta$. Let $g$ be an $(\varepsilon,\delta)$-approximation to the identity in the following sense:
\begin{enumerate}
\item $g\in L^1(\mathbb{R})$ and $\displaystyle \int_{\mathbb{R}} g(t)\,dt=1$,
\item $\displaystyle \int_{|t|\ge \delta} |g(t)|\,dt<\varepsilon$.
\end{enumerate}
Then for every $x\in[0,1]$,
\[
\label{eq:3.u185}
|(f*g)(x)-f(x)|\le (1+4M)\varepsilon.
\]
\end{lemma}

\begin{theorem}
\label{thm:3.12}
[Weierstrass approximation theorem I]
Let $f:\mathbb{R}\to\mathbb{R}$ be continuous and supported on $[0,1]$, i.e. $f(x)=0$ for all $x\notin[0,1]$. Then for every $\varepsilon>0$ there exists a polynomial $p\in\mathbb{R}[x]$ such that
\[
\label{eq:3.u193}
|p(x)-f(x)|\le \varepsilon\quad\text{for all }x\in[0,1].
\]
\end{theorem}

\begin{lemma}
\label{lem:3.5}
Let $f:[0,1]\to\mathbb{R}$ be continuous and satisfy $f(0)=f(1)=0$. Define $F:\mathbb{R}\to\mathbb{R}$ by
\[
\label{eq:3.u199}
F(x)=\begin{cases}f(x),&x\in[0,1],\\0,&x\notin[0,1].\end{cases}
\]
Then $F$ is continuous on $\mathbb{R}$.
\end{lemma}

proof:
\begin{proof}
\label{prf:lem:3.5}
Let $x_0\in\mathbb{R}$. If $x_0\in(0,1)$, then $F$ agrees with $f$ on a neighborhood of $x_0$, so $F$ is continuous at $x_0$ because $f$ is continuous on $[0,1]$.

If $x_0\notin[0,1]$, then there exists $\delta>0$ such that $(x_0-\delta,x_0+\delta)\cap[0,1]=\varnothing$. Hence $F(x)=0$ for all $x$ with $|x-x_0|<\delta$, so $F$ is constant on a neighborhood of $x_0$ and therefore continuous at $x_0$.

It remains to check $x_0=0$ and $x_0=1$. Let $\varepsilon>0$. Since $f$ is continuous at $0$ and $f(0)=0$, there exists $\delta_0>0$ such that $|f(x)|<\varepsilon$ whenever $x\in[0,1]$ and $|x-0|<\delta_0$. For $|x|<\delta_0$, either $x\in[0,1]$ and then $|F(x)-F(0)|=|f(x)|<\varepsilon$, or $x<0$ and then $F(x)=F(0)=0$, so $|F(x)-F(0)|=0<\varepsilon$. Thus $F$ is continuous at $0$.

Similarly, since $f$ is continuous at $1$ and $f(1)=0$, there exists $\delta_1>0$ such that $|f(x)|<\varepsilon$ whenever $x\in[0,1]$ and $|x-1|<\delta_1$. For $|x-1|<\delta_1$, either $x\in[0,1]$ and then $|F(x)-F(1)|=|f(x)|<\varepsilon$, or $x>1$ and then $F(x)=F(1)=0$, so $|F(x)-F(1)|=0<\varepsilon$. Thus $F$ is continuous at $1$.

Therefore $F$ is continuous at every $x_0\in\mathbb{R}$.
\end{proof}

