\begin{theorem}
\label{thm:3.13}
(Weierstrass approximation theorem II) Let $f:[0,1]\to\mathbb{R}$ be continuous and satisfy $f(0)=f(1)=0$. Then for every $\varepsilon>0$ there exists a polynomial $P$ such that
\[
\label{eq:3.u200}
\sup_{x\in[0,1]} |P(x)-f(x)|\le \varepsilon.
\]
\end{theorem}

proof:
\begin{proof}
\label{prf:thm:3.13}
Let $\varepsilon>0$. Define $g:[0,1]\to\mathbb{R}$ by
\[
\label{eq:3.u201}
g(x)=\begin{cases}
 \dfrac{f(x)}{x(1-x)}, & x\in(0,1),\\
 0, & x\in\{0,1\}.
 \end{cases}
\]
Since $f(0)=0$, continuity of $f$ at $0$ implies $\lim_{x\to 0^+} f(x)=0$, hence $\lim_{x\to 0^+} \frac{f(x)}{x}=0$. Because $1-x\to 1$ as $x\to 0^+$, it follows that $\lim_{x\to 0^+} \frac{f(x)}{x(1-x)}=0$, so $g$ is continuous at $0$. Similarly, using $f(1)=0$ and $\lim_{x\to 1^-} (1-x)=0$ gives $\lim_{x\to 1^-} \frac{f(x)}{x(1-x)}=0$, so $g$ is continuous at $1$. Therefore $g$ is continuous on $[0,1]$.

By the Weierstrass approximation theorem (uniform approximation of continuous functions on $[0,1]$ by polynomials), there exists a polynomial $Q$ such that
\[
\label{eq:3.u202}
\sup_{x\in[0,1]} |Q(x)-g(x)|\le 4\varepsilon.
\]
Define the polynomial $P(x)=x(1-x)Q(x)$. Then for $x\in(0,1)$,
\[
\label{eq:3.u203}
P(x)-f(x)=x(1-x)\bigl(Q(x)-g(x)\bigr),
\]
and the same identity holds at $x\in\{0,1\}$ since both sides equal $0$. Hence, for all $x\in[0,1]$,
\[
\label{eq:3.u204}
|P(x)-f(x)|\le x(1-x)\,\sup_{t\in[0,1]}|Q(t)-g(t)|\le \frac14\cdot 4\varepsilon=\varepsilon,
\]
because $0\le x(1-x)\le \tfrac14$ on $[0,1]$. This proves the claim.
\end{proof}

