\begin{theorem}
\label{thm:3.14}
[Weierstrass approximation theorem III]
Let $f:[0,1]\to\mathbb{R}$ be continuous. For every $\varepsilon>0$ there exists a polynomial $P:[0,1]\to\mathbb{R}$ such that
\[
\label{eq:3.u205}
\sup_{x\in[0,1]} |P(x)-f(x)|\le \varepsilon.
\]
\end{theorem}

\begin{theorem}
\label{thm:3.15}
[Weierstrass approximation theorem on $[a,b]$]
Let $a<b$ be real numbers, and let $f:[a,b]\to\mathbb{R}$ be continuous. Then for every $\varepsilon>0$ there exists a polynomial $P$ such that
\[
\label{eq:3.u209}
\sup_{y\in[a,b]} |P(y)-f(y)|\le \varepsilon.
\]
\end{theorem}

\begin{theorem}
\label{prop:3.8.2}
[Failure of uniform polynomial approximation on $\mathbb R$]
Continuous functions on $\mathbb R$ cannot, in general, be uniformly approximated by polynomials.
In particular, for $f(x)=e^x$ and for every polynomial $p$, one has
\[
\sup_{x\in\mathbb R}\,|e^x-p(x)|=+\infty.
\]
Hence there is no sequence of polynomials $(p_n)$ such that $p_n\to e^x$ uniformly on $\mathbb R$.

\end{theorem}
